CREATE TYPE public.asset_event_kind AS ENUM ('manutencao','reparo','substituicao','observacao');
CREATE TYPE public.capture_ai_status AS ENUM ('pendente','processando','pronto','erro');
CREATE TYPE public.capture_kind AS ENUM ('foto','texto','email');
CREATE TYPE public.capture_review_status AS ENUM ('pendente','aplicado','descartado');
CREATE TYPE public.chat_role AS ENUM ('user','assistant');
CREATE TYPE public.expense_kind AS ENUM ('fixo','variavel','eventual','sazonal');
CREATE TYPE public.household_kind AS ENUM ('casa','apartamento','sitio','praia','alugado','outro');
CREATE TYPE public.layer_key AS ENUM ('veiculos','pets','jardim');
CREATE TYPE public.member_role AS ENUM ('owner','manager','member','viewer','guest');
CREATE TYPE public.obligation_frequency AS ENUM ('one_time','monthly','quarterly','semiannual','yearly','custom');
CREATE TYPE public.obligation_kind AS ENUM ('conta','tributo','seguro','revisao','vacina','contrato','outro');
CREATE TYPE public.occurrence_status AS ENUM ('pendente','pago','feito');
CREATE TYPE public.project_status AS ENUM ('planejado','andamento','concluido');
CREATE TYPE public.room_area AS ENUM ('interna','externa','garagem');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, name text, email text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.households (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, kind public.household_kind NOT NULL DEFAULT 'casa', address text, timezone text NOT NULL DEFAULT 'America/Sao_Paulo', created_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.households TO authenticated; GRANT ALL ON public.households TO service_role;
ALTER TABLE public.households ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.household_members (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), household_id uuid NOT NULL REFERENCES public.households(id) ON DELETE CASCADE, user_id uuid, invited_email text, role public.member_role NOT NULL DEFAULT 'member', expires_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(household_id,user_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.household_members TO authenticated; GRANT ALL ON public.household_members TO service_role;
ALTER TABLE public.household_members ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.is_member(_household_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.household_members WHERE household_id = _household_id AND user_id = auth.uid() AND (expires_at IS NULL OR expires_at > now())) $$;
CREATE FUNCTION public.can_write(_household_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.household_members WHERE household_id = _household_id AND user_id = auth.uid() AND role IN ('owner','manager','member') AND (expires_at IS NULL OR expires_at > now())) $$;
CREATE FUNCTION public.can_manage(_household_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.household_members WHERE household_id = _household_id AND user_id = auth.uid() AND role IN ('owner','manager') AND (expires_at IS NULL OR expires_at > now())) $$;
CREATE POLICY households_read ON public.households FOR SELECT TO authenticated USING (public.is_member(id));
CREATE POLICY households_update ON public.households FOR UPDATE TO authenticated USING (public.can_manage(id)) WITH CHECK (public.can_manage(id));
CREATE POLICY households_delete ON public.households FOR DELETE TO authenticated USING (EXISTS (SELECT 1 FROM public.household_members WHERE household_id = households.id AND user_id = auth.uid() AND role = 'owner' AND (expires_at IS NULL OR expires_at > now())));
CREATE POLICY members_read ON public.household_members FOR SELECT TO authenticated USING (public.is_member(household_id));
CREATE POLICY members_insert ON public.household_members FOR INSERT TO authenticated WITH CHECK (public.can_manage(household_id) AND role <> 'owner' AND user_id IS NULL);
CREATE POLICY members_update ON public.household_members FOR UPDATE TO authenticated USING (public.can_manage(household_id) AND role <> 'owner') WITH CHECK (public.can_manage(household_id) AND role <> 'owner');
CREATE POLICY members_delete ON public.household_members FOR DELETE TO authenticated USING (public.can_manage(household_id) AND role <> 'owner');
CREATE FUNCTION public.profiles_visible(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT _user_id = auth.uid() OR EXISTS (SELECT 1 FROM public.household_members m WHERE m.user_id = _user_id AND public.is_member(m.household_id) AND (m.expires_at IS NULL OR m.expires_at > now())) $$;
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING (public.profiles_visible(id));
CREATE POLICY profiles_insert ON public.profiles FOR INSERT TO authenticated WITH CHECK (id = auth.uid());
CREATE POLICY profiles_update ON public.profiles FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id,name,email) VALUES (NEW.id,NEW.raw_user_meta_data->>'name',NEW.email) ON CONFLICT(id) DO NOTHING; RETURN NEW; END $$;
CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();
CREATE FUNCTION public.create_household(_name text, _kind text DEFAULT 'casa', _address text DEFAULT NULL) RETURNS public.households LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE h public.households; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Autenticação necessária'; END IF; IF length(trim(_name)) = 0 THEN RAISE EXCEPTION 'O lar precisa de um nome'; END IF; INSERT INTO public.households(name,kind,address,created_by) VALUES(trim(_name),_kind::public.household_kind,_address,auth.uid()) RETURNING * INTO h; INSERT INTO public.household_members(household_id,user_id,role) VALUES(h.id,auth.uid(),'owner'); RETURN h; END $$;
CREATE FUNCTION public.claim_invites() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE n integer; verified_email text; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Autenticação necessária'; END IF; SELECT lower(email) INTO verified_email FROM auth.users WHERE id=auth.uid() AND email_confirmed_at IS NOT NULL; IF verified_email IS NULL THEN RETURN 0; END IF; UPDATE public.household_members m SET user_id=auth.uid() WHERE m.user_id IS NULL AND lower(m.invited_email)=verified_email AND (m.expires_at IS NULL OR m.expires_at > now()) AND NOT EXISTS (SELECT 1 FROM public.household_members own WHERE own.household_id=m.household_id AND own.user_id=auth.uid()); GET DIAGNOSTICS n=ROW_COUNT; RETURN n; END $$;
CREATE TABLE public.rooms (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), household_id uuid NOT NULL REFERENCES public.households(id) ON DELETE CASCADE, name text NOT NULL, kind text NOT NULL DEFAULT 'outro', kind_area public.room_area NOT NULL DEFAULT 'interna', layout jsonb NOT NULL DEFAULT '{}', sort_order integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.rooms TO authenticated; GRANT ALL ON public.rooms TO service_role; ALTER TABLE public.rooms ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.assets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), household_id uuid NOT NULL REFERENCES public.households(id) ON DELETE CASCADE, room_id uuid REFERENCES public.rooms(id) ON DELETE SET NULL, name text NOT NULL, category text NOT NULL DEFAULT 'outro', brand text, model text, serial text, purchase_date date, purchase_price numeric, store text, warranty_expires date, extended_warranty_expires date, useful_life_months integer, photo_url text, notes text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.assets TO authenticated; GRANT ALL ON public.assets TO service_role; ALTER TABLE public.assets ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.providers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), household_id uuid NOT NULL REFERENCES public.households(id) ON DELETE CASCADE, name text NOT NULL, specialty text, phone text, trusted boolean NOT NULL DEFAULT false, notes text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.providers TO authenticated; GRANT ALL ON public.providers TO service_role; ALTER TABLE public.providers ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.vehicles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), household_id uuid NOT NULL REFERENCES public.households(id) ON DELETE CASCADE, name text NOT NULL, plate text, brand text, model text, year integer, purchase_date date, odometer numeric, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.vehicles TO authenticated; GRANT ALL ON public.vehicles TO service_role; ALTER TABLE public.vehicles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.pets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), household_id uuid NOT NULL REFERENCES public.households(id) ON DELETE CASCADE, name text NOT NULL, species text, breed text, birthdate date, weight_kg numeric, photo_url text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.pets TO authenticated; GRANT ALL ON public.pets TO service_role; ALTER TABLE public.pets ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.plants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), household_id uuid NOT NULL REFERENCES public.households(id) ON DELETE CASCADE, name text NOT NULL, location text, watering_interval_days integer, last_watered date, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.plants TO authenticated; GRANT ALL ON public.plants TO service_role; ALTER TABLE public.plants ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), household_id uuid NOT NULL REFERENCES public.households(id) ON DELETE CASCADE, room_id uuid REFERENCES public.rooms(id) ON DELETE SET NULL, asset_id uuid REFERENCES public.assets(id) ON DELETE SET NULL, vehicle_id uuid REFERENCES public.vehicles(id) ON DELETE SET NULL, pet_id uuid REFERENCES public.pets(id) ON DELETE SET NULL, title text NOT NULL, category text NOT NULL DEFAULT 'outro', expires_at date, file_url text, notes text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.documents TO authenticated; GRANT ALL ON public.documents TO service_role; ALTER TABLE public.documents ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.obligations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), household_id uuid NOT NULL REFERENCES public.households(id) ON DELETE CASCADE, title text NOT NULL, kind public.obligation_kind NOT NULL DEFAULT 'outro', amount numeric, frequency public.obligation_frequency NOT NULL DEFAULT 'one_time', custom_interval_days integer, next_due date, room_id uuid REFERENCES public.rooms(id) ON DELETE SET NULL, asset_id uuid REFERENCES public.assets(id) ON DELETE SET NULL, vehicle_id uuid REFERENCES public.vehicles(id) ON DELETE SET NULL, pet_id uuid REFERENCES public.pets(id) ON DELETE SET NULL, responsible_member_id uuid REFERENCES public.household_members(id) ON DELETE SET NULL, auto_renew boolean NOT NULL DEFAULT false, notes text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.obligations TO authenticated; GRANT ALL ON public.obligations TO service_role; ALTER TABLE public.obligations ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.obligation_occurrences (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), obligation_id uuid NOT NULL REFERENCES public.obligations(id) ON DELETE CASCADE, due_date date NOT NULL, status public.occurrence_status NOT NULL DEFAULT 'pendente', paid_at timestamptz, amount_paid numeric, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(obligation_id,due_date));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.obligation_occurrences TO authenticated; GRANT ALL ON public.obligation_occurrences TO service_role; ALTER TABLE public.obligation_occurrences ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.asset_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid NOT NULL REFERENCES public.assets(id) ON DELETE CASCADE, kind public.asset_event_kind NOT NULL DEFAULT 'observacao', date date NOT NULL DEFAULT CURRENT_DATE, description text NOT NULL, cost numeric, provider_id uuid, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.asset_events TO authenticated; GRANT ALL ON public.asset_events TO service_role; ALTER TABLE public.asset_events ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.provider_services (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider_id uuid NOT NULL REFERENCES public.providers(id) ON DELETE CASCADE, asset_id uuid REFERENCES public.assets(id) ON DELETE SET NULL, date date NOT NULL DEFAULT CURRENT_DATE, description text NOT NULL, cost numeric, rating integer, would_hire_again boolean, notes text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.provider_services TO authenticated; GRANT ALL ON public.provider_services TO service_role; ALTER TABLE public.provider_services ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.expenses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), household_id uuid NOT NULL REFERENCES public.households(id) ON DELETE CASCADE, room_id uuid REFERENCES public.rooms(id) ON DELETE SET NULL, asset_id uuid REFERENCES public.assets(id) ON DELETE SET NULL, category text NOT NULL DEFAULT 'outro', amount numeric NOT NULL, date date NOT NULL DEFAULT CURRENT_DATE, kind public.expense_kind NOT NULL DEFAULT 'variavel', description text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.expenses TO authenticated; GRANT ALL ON public.expenses TO service_role; ALTER TABLE public.expenses ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.projects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), household_id uuid NOT NULL REFERENCES public.households(id) ON DELETE CASCADE, name text NOT NULL, budget_planned numeric, budget_spent numeric NOT NULL DEFAULT 0, status public.project_status NOT NULL DEFAULT 'planejado', start_date date, end_date date, notes text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.projects TO authenticated; GRANT ALL ON public.projects TO service_role; ALTER TABLE public.projects ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.captures (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), household_id uuid NOT NULL REFERENCES public.households(id) ON DELETE CASCADE, kind public.capture_kind NOT NULL DEFAULT 'texto', raw_text text, image_url text, ai_status public.capture_ai_status NOT NULL DEFAULT 'pendente', ai_extract jsonb, review_status public.capture_review_status NOT NULL DEFAULT 'pendente', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.captures TO authenticated; GRANT ALL ON public.captures TO service_role; ALTER TABLE public.captures ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.chat_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), household_id uuid NOT NULL REFERENCES public.households(id) ON DELETE CASCADE, member_id uuid REFERENCES public.household_members(id) ON DELETE SET NULL, role public.chat_role NOT NULL, content text NOT NULL, citations jsonb, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.chat_messages TO authenticated; GRANT ALL ON public.chat_messages TO service_role; ALTER TABLE public.chat_messages ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.household_layers (household_id uuid NOT NULL REFERENCES public.households(id) ON DELETE CASCADE, layer public.layer_key NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(household_id,layer));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.household_layers TO authenticated; GRANT ALL ON public.household_layers TO service_role; ALTER TABLE public.household_layers ENABLE ROW LEVEL SECURITY;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['rooms','assets','providers','vehicles','pets','plants','documents','obligations','expenses','projects','captures','chat_messages','household_layers'] LOOP EXECUTE format('CREATE POLICY read_members ON public.%I FOR SELECT TO authenticated USING (public.is_member(household_id))', t); EXECUTE format('CREATE POLICY insert_members ON public.%I FOR INSERT TO authenticated WITH CHECK (public.can_write(household_id))', t); EXECUTE format('CREATE POLICY update_members ON public.%I FOR UPDATE TO authenticated USING (public.can_write(household_id)) WITH CHECK (public.can_write(household_id))', t); EXECUTE format('CREATE POLICY delete_members ON public.%I FOR DELETE TO authenticated USING (public.can_write(household_id))', t); EXECUTE format('CREATE INDEX ON public.%I (household_id)',t); END LOOP; END $$;
CREATE POLICY events_read ON public.asset_events FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.assets a WHERE a.id=asset_id AND public.is_member(a.household_id)));
CREATE POLICY events_write ON public.asset_events FOR ALL TO authenticated USING (EXISTS (SELECT 1 FROM public.assets a WHERE a.id=asset_id AND public.can_write(a.household_id))) WITH CHECK (EXISTS (SELECT 1 FROM public.assets a WHERE a.id=asset_id AND public.can_write(a.household_id)));
CREATE POLICY occurrences_read ON public.obligation_occurrences FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.obligations o WHERE o.id=obligation_id AND public.is_member(o.household_id)));
CREATE POLICY occurrences_write ON public.obligation_occurrences FOR ALL TO authenticated USING (EXISTS (SELECT 1 FROM public.obligations o WHERE o.id=obligation_id AND public.can_write(o.household_id))) WITH CHECK (EXISTS (SELECT 1 FROM public.obligations o WHERE o.id=obligation_id AND public.can_write(o.household_id)));
CREATE POLICY services_read ON public.provider_services FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.providers p WHERE p.id=provider_id AND public.is_member(p.household_id)));
CREATE POLICY services_write ON public.provider_services FOR ALL TO authenticated USING (EXISTS (SELECT 1 FROM public.providers p WHERE p.id=provider_id AND public.can_write(p.household_id))) WITH CHECK (EXISTS (SELECT 1 FROM public.providers p WHERE p.id=provider_id AND public.can_write(p.household_id)));
CREATE INDEX ON public.household_members(user_id);
CREATE INDEX ON public.asset_events(asset_id);
CREATE INDEX ON public.provider_services(provider_id);
CREATE INDEX ON public.provider_services(asset_id);
REVOKE ALL ON FUNCTION public.is_member(uuid), public.can_write(uuid), public.can_manage(uuid), public.profiles_visible(uuid), public.create_household(text,text,text), public.claim_invites(), public.handle_new_user() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.is_member(uuid), public.can_write(uuid), public.can_manage(uuid), public.profiles_visible(uuid), public.create_household(text,text,text), public.claim_invites() TO authenticated, service_role;